{
  "steps": [
    {
      "title": "დაკეტე წყალი",
      "text": "მოატრიალე ონკანი საათის ისრის მიმართულებით ბოლომდე. შემდეგ მეორეც დაკეტე.",
      "focus": ["p2", "p3"],
      "avoid": [],
      "markers": [
        {"part": "p2", "label": "პირველი ონკანი", "tone": "brand"},
        {"part": "p3", "label": "მეორე ონკანი", "tone": "brand"}
      ],
      "arrows": [
        {"part": "p2", "type": "rotate", "dir": "cw"},
        {"part": "p3", "type": "rotate", "dir": "cw"}
      ],
      "tools": [],
      "warn": "დაკეტე ნაზად; თუ ონკანი გაჭედილია, ძალა არ დაატანო."
    },
    {
      "title": "ჩადგი ვედრო სიფონის ქვეშ",
      "text": "სიფონში წყალი დგას. გახსნისას ჩამოიღვრება, ამიტომ ვედრო ან ღრმა თასი პირდაპირ მის ქვეშ დადგი.",
      "focus": ["p6"],
      "avoid": [],
      "markers": [
        {"part": "p6", "label": "ვედროს დასადგმელი ადგილი", "tone": "brand"}
      ],
      "arrows": [],
      "tools": ["ვედრო ან ღრმა თასი"],
      "warn": null
    },
    {
      "title": "მოუშვი ქანჩი",
      "text": "ეს ქანჩი ჟონავს. ხელით მოუშვი საათის ისრის საწინააღმდეგოდ. პლასტმასისაა, გასაღები არ დაგჭირდება.",
      "focus": ["p1"],
      "avoid": ["p2", "p3"],
      "markers": [
        {"part": "p1", "label": "სავარაუდო მოსაშვები ქანჩი", "tone": "brand"}
      ],
      "arrows": [
        {"part": "p1", "type": "rotate", "dir": "ccw"}
      ],
      "tools": [],
      "warn": "სამიზნედ დაშვებულია ზედა ქანჩი p1; მარჯვენა ქანჩიც p4 შესაძლო კანდიდატია. მოცემული აღწერით გაჟონვის ადგილი დადასტურებული არ არის — გახსნამდე გადაამოწმე. მოშვებისას სიფონი ხელით დაიჭირე."
    },
    {
      "title": "შეამოწმე შუასადები",
      "text": "მოხსენი სიფონი და ნახე ქანჩის შიგნით რეზინის რგოლი. თუ დაბზარულია ან გვერდზეა გადაწეული, შეცვალე. ზომა: 40 მმ.",
      "focus": ["p5", "p1"],
      "avoid": ["p2", "p3"],
      "markers": [
        {"part": "p5", "label": "მოსახსნელი სიფონი", "tone": "brand"},
        {"part": "p1", "label": "შუასადების სავარაუდო მდებარეობა", "tone": "neutral"}
      ],
      "arrows": [],
      "tools": ["შესაბამისი ზომის ახალი შუასადები"],
      "warn": "რეზინის რგოლი შიგნითაა და ხილულ ნაწილებში არ არის მონიშნული; p1-ის არჩევა წინა ნაბიჯის დაშვებას ეყრდნობა. სიფონის მოსახსნელად შესაძლოა p4-ის მოშვებაც გახდეს საჭირო — მილს ძალით ნუ მოქაჩავ. 40 მმ ინსტრუქციაშია მითითებული და ფოტოდან დადასტურებული არ არის; ზომა შეძენამდე გადაამოწმე."
    },
    {
      "title": "მოუჭირე და შეამოწმე",
      "text": "ხელით მოუჭირე ბოლომდე, შემდეგ კიდევ მეოთხედი ბრუნი. გახსენი წყალი და ერთი წუთი დააკვირდი.",
      "focus": ["p1", "p2", "p3"],
      "avoid": [],
      "markers": [
        {"part": "p1", "label": "მოჭერა და გაჟონვის შემოწმება", "tone": "brand"},
        {"part": "p2", "label": "წყლის გახსნა", "tone": "brand"},
        {"part": "p3", "label": "წყლის გახსნა", "tone": "brand"}
      ],
      "arrows": [
        {"part": "p1", "type": "rotate", "dir": "cw"},
        {"part": "p2", "type": "rotate", "dir": "ccw"},
        {"part": "p3", "type": "rotate", "dir": "ccw"}
      ],
      "tools": [],
      "warn": "p1 კვლავ სავარაუდო სამიზნეა; თუ p4-იც მოხსენი, ისიც საიმედოდ დააბრუნე. დამატებითი მეოთხედი ბრუნი უნივერსალური მოთხოვნა არ არის — პლასტმასი არ გადაჭიმო და დაიცავი მწარმოებლის მითითება. სიფონის შესამოწმებლად ნიჟარის ონკანიც გაუშვი; ის ნაწილების სიაში არ ჩანს."
    }
  ],
  "unknown_parts": [
    "ქანჩის შიგნით არსებული რეზინის შუასადები — გარედან უხილავია და ID არ აქვს.",
    "ნიჟარის ონკანი, საიდანაც წყალი უნდა გაუშვა სიფონის შესამოწმებლად — ნაწილების სიაში არ არის."
  ]
}
